def rank(xs):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in xs.items() if np.isfinite(v))
    if len(good) >= 2:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


