import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_DAYS = 10
MIN_W, MAX_W = 0.015, 0.16
_last_decision = None


def load_ensemble():
    try:
        obj = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        return obj.get("selected_factors", [])[:10]
    except (OSError, ValueError, TypeError):
        return []


def cs_rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    n = len(valid)
    if n > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / n
    return out


def bounded_weights(raw):
    # Project to a long-only, fully invested simplex with sensible concentration.
    w = {s: max(float(raw.get(s, 0.0)), 1e-10) for s in UNIVERSE}
    for _ in range(30):
        total = sum(w.values())
        w = {s: v / total for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = set(low + high)
        for s in low:
            w[s] = MIN_W
        for s in high:
            w[s] = MAX_W
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        if not free or rem <= 0:
            break
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / z
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    factors = load_ensemble()
    if not factors:
        return

    # Use only the 15 tradable benchmark assets; observation-only macro series are excluded.
    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        data[symbol] = (close, high, low, ret, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return

    decision = max(x[4] for x in data.values())
    if _last_decision is not None:
        gap = (np.datetime64(decision, "D") - np.datetime64(_last_decision, "D")) / np.timedelta64(1, "D")
        if gap < REBALANCE_DAYS:
            return

    raw = {fid: {} for fid in [str(f.get("factor_id")) for f in factors]}
    invvol = {}
    five_day = {}
    for symbol, (c, h, l, r, _) in data.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        invvol[symbol] = 1.0 / vol
        five_day[symbol] = c[-1] / max(c[-6], 1e-12) - 1.0
        if "miner_3_clv_1d" in raw:
            # CLV is a one-day close-location signal, winsorized by rank normalization.
            raw["miner_3_clv_1d"][symbol] = (2*c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12)
        if "peer_median_leadlag_5d" in raw:
            raw["peer_median_leadlag_5d"][symbol] = five_day[symbol]
        if "short_term_reversal_5d" in raw:
            raw["short_term_reversal_5d"][symbol] = -float(np.mean(r[-5:]))
        if "miner_2_risk_adjusted_momentum_20d" in raw:
            raw["miner_2_risk_adjusted_momentum_20d"][symbol] = (c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01)
        if "miner_2_intraday_reversal_20260827" in raw:
            raw["miner_2_intraday_reversal_20260827"][symbol] = -float(r[-1])

    if "peer_median_leadlag_5d" in raw:
        med = float(np.median(list(five_day.values())))
        raw["peer_median_leadlag_5d"] = {s: v - med for s, v in five_day.items()}

    ranked = {fid: cs_rank(vals) for fid, vals in raw.items()}
    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        fid = str(f.get("factor_id"))
        if fid not in ranked:
            continue
        weight = float(f.get("weight", 0.0))
        direction = float(f.get("direction", 1.0))
        for s in UNIVERSE:
            score[s] += weight * direction * (ranked[fid].get(s, 0.5) - 0.5)

    mean_iv = float(np.mean(list(invvol.values())))
    # Bullish regime: retain signal exposure, with a modest volatility brake.
    raw_weight = {s: max(score[s], 0.01) * (0.78 + 0.22 * invvol.get(s, mean_iv) / mean_iv) for s in UNIVERSE}
    weights = bounded_weights(raw_weight)
    score_array = np.asarray([score[s] for s in UNIVERSE], dtype=float)
    scale = max(float(score_array.std()), 1e-12)
    forecast = {s: float(0.01 * (score[s] - score_array.mean()) / scale) for s in UNIVERSE}
    factor_ids = [str(f.get("factor_id")) for f in factors]
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _last_decision = decision

