    for p in (Path(__file__).parent / "factor_ensemble.json", Path(__file__).parent / "factors" / "factor_ensemble.json"):
        try:
            x = json.loads(p.read_text(encoding="utf-8"))
            return x.get("selected_factors", [])[:10]
        except (OSError, ValueError, TypeError):
            pass
    return []


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    n = len(a)
    if n > 1:
        for i, (s, _) in enumerate(a):
            out[s] = (i + 1.0) / n
    return out


def bounded(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    for _ in range(30):
