import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.20
REBALANCE_DAYS = 10
_last_decision = None


def load_factors():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        return json.loads(p.read_text(encoding="utf-8")).get("selected_factors", [])[:10]
    except Exception:
        return []


def percentile_rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n > 1 else 0.5
    return out


def bounded(raw):
    # Iterative capped-simplex projection, preserving a complete 15-asset target.
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    for _ in range(60):
        z = sum(w.values())
        w = {s: v / z for s, v in w.items()}
        low = {s for s in UNIVERSE if w[s] < MIN_W}
        high = {s for s in UNIVERSE if w[s] > MAX_W}
        fixed = low | high
        if not fixed:
            break
        for s in low: w[s] = MIN_W
        for s in high: w[s] = MAX_W
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        if not free or rem <= 0: break
        total = sum(w[s] for s in free)
        for s in free: w[s] *= rem / max(total, 1e-12)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    factors = load_factors()
    if not factors or len(factors) > 10:
        return
    ids = [str(f["factor_id"]) for f in factors]
    fw = {str(f["factor_id"]): float(f["weight"]) for f in factors}
    fd = {str(f["factor_id"]): int(f["direction"]) for f in factors}
    if set(ids) != set(fw) or abs(sum(fw.values()) - 1.0) > 1e-6:
        return

    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=140)
        if df is None or len(df) < 65: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, r, str(df.iloc[-1]["date"]))
    if len(data) < 12: return
    decision = max(x[2] for x in data.values())
    if _last_decision is not None:
        gap = (np.datetime64(decision) - np.datetime64(_last_decision)) / np.timedelta64(1, "D")
        if gap < REBALANCE_DAYS: return

    ret10 = {s: x[0][-1] / x[0][-11] - 1 for s, x in data.items()}
    ret15 = {s: x[0][-1] / x[0][-16] - 1 for s, x in data.items()}
    ret20 = {s: x[0][-1] / x[0][-21] - 1 for s, x in data.items()}
    ret30 = {s: x[0][-1] / x[0][-31] - 1 for s, x in data.items()}
    med10, med15, med20, med30 = [np.median(list(x.values())) for x in (ret10, ret15, ret20, ret30)]
    # Reversal is conditional: do not aggressively fade a broad positive tape.
    bearish = med20 < 0.0 and med30 < 0.0
    feats = {fid: {} for fid in ids}
    invvol = {}
    for s, (c, r, _) in data.items():
        v20, v60 = max(float(np.std(r[-20:])), .008), max(float(np.std(r[-60:])), .008)
        invvol[s] = 1.0 / v20
        vals = {
            "miner_2_20280113_conditional_medium_reversal_20d": (-(ret20[s]-med20)/v60) if bearish else 0.0,
            "miner_1_20271118_macro_relative_strength_reversal": -(ret10[s]-med10)/v20,
            "miner_2_20271230_medium_volscaled_reversal_20_30": -(ret20[s]-med20)/v60,
            "miner_2_20280127_short_trend_reversal_15d": -(ret15[s]-med15)/v20,
            "miner_2_20271202_risk_adjusted_momentum_reversal": -(ret10[s]-med10)/v20,
            "miner_3_20271104_volnorm_momentum_reversal": -np.mean(r[-5:])/v20,
            "miner_3_20271216_medium_reversal_30d": -(ret30[s]-med30)/v60,
            "miner_3_20280210_slow_reversal_confirm30d": (-(ret30[s]-med30)/v60) * (1.0 if np.sign(ret20[s]) == np.sign(ret30[s]) else .5),
            "miner_2_20271104_vol_compression": -(v20/v60),
        }
        for fid in ids: feats[fid][s] = vals.get(fid, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for fid in ids:
        rr = percentile_rank(feats[fid])
        for s in UNIVERSE: score[s] += fw[fid] * fd[fid] * (rr[s] - .5)
