    if not factors or len(factors) > 10:
        return
    ids = [str(x["factor_id"]) for x in factors]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in factors}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in factors}
