import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.20
_days_to_rebalance = 0


def load_ensemble():
    try:
        obj = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())
        fs = obj.get("selected_factors", [])
        if not fs or len(fs) > 10 or abs(sum(float(x["weight"]) for x in fs) - 1.0) > 1e-6:
            return []
        return fs
    except Exception:
        return []


def rank_signal(signal, symbols):
    vals = sorted([(s, float(signal.get(s, 0.0))) for s in symbols], key=lambda z: z[1])
    n = len(vals)
    return {s: (i + 1) / n for i, (s, _) in enumerate(vals)}


def bounded_weights(raw):
    w = {s: max(float(raw.get(s, 1e-8)), 1e-8) for s in UNIVERSE}
    fixed = {}
    for _ in range(25):
        free = [s for s in UNIVERSE if s not in fixed]
        remain = 1.0 - sum(fixed.values())
        denom = sum(w[s] for s in free) or 1.0
        clipped = False
        for s in free:
            q = remain * w[s] / denom
            if q < MIN_W:
                fixed[s] = MIN_W
                clipped = True
            elif q > MAX_W:
                fixed[s] = MAX_W
                clipped = True
        if not clipped:
            fixed.update({s: remain * w[s] / denom for s in free})
            break
    if len(fixed) != len(UNIVERSE):
        fixed = {s: 1.0 / len(UNIVERSE) for s in UNIVERSE}
    total = sum(fixed.values())
    return {s: fixed[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    fs = load_ensemble()
    if not fs:
        return

    # Preserve the screener ensemble exactly in the execution contract.
    ids = [str(x["factor_id"]) for x in fs]
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in fs}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in fs}

    prices = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=150)
        if df is not None and len(df) >= 70:
            prices[symbol] = np.asarray(df.sort_values("date")["close"], dtype=float)
    if len(prices) < 12:
        return
    symbols = list(prices)
    returns = {s: prices[s][1:] / np.maximum(prices[s][:-1], 1e-12) - 1.0 for s in symbols}

    def horizon(k):
        return {s: prices[s][-1] / max(prices[s][-k-1], 1e-12) - 1.0 for s in symbols}

    r5, r10, r15, r20, r30 = [horizon(k) for k in (5, 10, 15, 20, 30)]
    v20 = {s: max(float(np.std(returns[s][-20:])), 0.008) for s in symbols}
    v60 = {s: max(float(np.std(returns[s][-60:])), 0.008) for s in symbols}
    downside60 = {s: max(float(np.std(np.minimum(returns[s][-60:], 0.0))), 0.006) for s in symbols}
    med5, med20, med30 = (float(np.median(list(x.values()))) for x in (r5, r20, r30))

    def reversal(x, vol):
        med = float(np.median(list(x.values())))
        return {s: -(x[s] - med) / vol[s] for s in symbols}

    defensive = ("XAU", "US10Y", "CN10Y")
