    signals = {
        # Downside-risk-adjusted reversal: penalize assets with larger downside risk.
        "miner_1_20281019_downside_risk_adjusted_reversal": {
            s: -(r20[s] - med20) / downside60[s] for s in symbols
        },
        "miner_2_20280113_conditional_medium_reversal_20d": rev20_v60 if med20 < 0 and med30 < 0 else {s: 0.35 * rev20_v60[s] for s in symbols},
        "miner_1_20271118_macro_relative_strength_reversal": {
            s: -(r10[s] - np.mean([r10.get(a, 0.0) for a in defensive])) / v20[s] for s in symbols
        },
        "miner_2_20271230_medium_volscaled_reversal_20_30": {s: 0.6 * rev20_v60[s] + 0.4 * reversal(r30, v60)[s] for s in symbols},
        "miner_2_20271202_risk_adjusted_momentum_reversal": reversal(r10, v20),
        "miner_2_20280127_short_trend_reversal_15d": reversal(r15, v20),
        "miner_3_20280210_slow_reversal_confirm30d": reversal(r30, v60),
        "miner_3_20271104_volnorm_momentum_reversal": reversal(r15, v20),
        "miner_2_20280601_vix_stress_reversal_20d": {s: rev20_v60[s] * (1.0 + 6.0 * max(0.0, -med5)) for s in symbols},
        "miner_2_20280921_downside_dispersion_shock_reversal_10d": reversal(r5, v20),
    }

    score = {s: 0.5 for s in UNIVERSE}
    for fid in ids:
        ranked = rank_signal(signals.get(fid, {}), symbols)
        for s in UNIVERSE:
            score[s] += factor_weights[fid] * directions[fid] * (ranked.get(s, 0.5) - 0.5)

    avg_inv_vol = np.mean([1.0 / v20[s] for s in symbols])
    raw = {s: max(score[s], 0.02) * (0.7 + 0.3 * (1.0 / v20.get(s, 0.02)) / avg_inv_vol) for s in UNIVERSE}
    dispersion = float(np.std(list(r5.values())))
    if med20 < 0 or med30 < 0 or dispersion > 0.02:
        for s in defensive:
            raw[s] *= 1.35
    target = bounded_weights(raw)

    # Deterministic 10-day forecast is required by the migration-cost gate.
    mean_score = float(np.mean(list(score.values())))
    score_sd = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean_score) / score_sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _days_to_rebalance = 9

