import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.20
_days_to_rebalance = 0


def load_ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text()).get("selected_factors", [])
        return fs if fs and len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs)-1) < 1e-6 else []
    except Exception:
        return []


def ranks(x):
    a = sorted(UNIVERSE, key=lambda s: float(x[s]))
    return {s: (a.index(s)+1)/len(a) for s in UNIVERSE}


def bounded(raw):
    w = {s: max(float(raw[s]), 1e-9) for s in UNIVERSE}
    for _ in range(30):
        fixed = {s: v for s, v in w.items() if v <= MIN_W or v >= MAX_W}
        # iterative clipping after proportional normalization
        z = sum(w.values())
        q = {s: w[s]/z for s in UNIVERSE}
        changed = False
        for s in UNIVERSE:
            if q[s] < MIN_W: w[s] = MIN_W; changed = True
            elif q[s] > MAX_W: w[s] = MAX_W; changed = True
            else: w[s] = q[s]
        if not changed: break
    z = sum(w.values())
    return {s: w[s]/z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    fs = load_ensemble()
    if not fs: return
    factor_ids = [str(x["factor_id"]) for x in fs]
    fw = {str(x["factor_id"]): float(x["weight"]) for x in fs}
    fd = {str(x["factor_id"]): int(x.get("direction", 1)) for x in fs}
    px = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 125: return
        px[s] = np.asarray(d.sort_values("date")["close"], dtype=float)
    r = {s: px[s][1:]/np.maximum(px[s][:-1], 1e-12)-1 for s in UNIVERSE}
    def ret(k): return {s: px[s][-1]/max(px[s][-k-1], 1e-12)-1 for s in UNIVERSE}
    r5,r10,r20,r30,r60,r120 = [ret(k) for k in (5,10,20,30,60,120)]
    v20={s:max(float(np.std(r[s][-20:])),.008) for s in UNIVERSE}
    v40={s:max(float(np.std(r[s][-40:])),.008) for s in UNIVERSE}
    v60={s:max(float(np.std(r[s][-60:])),.008) for s in UNIVERSE}
    down={s:max(float(np.std(np.minimum(r[s][-60:],0))),.006) for s in UNIVERSE}
    down30={s:max(float(np.std(np.minimum(r[s][-30:],0))),.006) for s in UNIVERSE}
    med=lambda x: float(np.median(list(x.values())))
    rev20={s:-(r20[s]-med(r20))/v40[s] for s in UNIVERSE}
    rev30={s:-(r30[s]-med(r30))/v40[s] for s in UNIVERSE}
    mean60={s:float(np.mean(r[s][-60:])) for s in UNIVERSE}
    signals={
      "miner_2_20281102_trend_persistence_60d": {s:r60[s]*np.sign(mean60[s])/v40[s] for s in UNIVERSE},
      "miner_1_20281019_downside_risk_adjusted_reversal": {s:-(r20[s]-med(r20))/down[s] for s in UNIVERSE},
      "miner_1_20281214_vol_compression_reversal": {s:-r20[s]*(1+float(np.clip(1-v20[s]/v60[s],-.5,.5))) for s in UNIVERSE},
      "miner_2_20280113_conditional_medium_reversal_20d": rev20,
      "miner_1_20271118_macro_relative_strength_reversal": {s:-(r10[s]-np.mean([r10['XAU'],r10['US10Y'],r10['CN10Y']]))/v20[s] for s in UNIVERSE},
      "miner_2_20271230_medium_volscaled_reversal_20_30": {s:.6*rev20[s]+.4*rev30[s] for s in UNIVERSE},
      "miner_1_20281130_inverted_120d_risk_trend": {s:-r120[s]/(np.sqrt(60)*v60[s])*(1+.25*np.sign(r20[s])) for s in UNIVERSE},
      "miner_3_20290125_lowvol_reversal_5d": {s:-r5[s]/(v20[s]*np.sqrt(5)) for s in UNIVERSE},
      "miner_1_20290125_shock_reversal": {s:-r5[s]/v20[s] for s in UNIVERSE},
      "miner_3_20290111_downside_asymmetry_30d": {s:-down30[s]/max(v20[s],.008) for s in UNIVERSE},
    }
    score={s:.5 for s in UNIVERSE}
    for fid in factor_ids:
        if fid not in signals: return
        rr=ranks(signals[fid])
        for s in UNIVERSE: score[s] += fw[fid]*fd[fid]*(rr[s]-.5)
    inv=np.mean([1/v20[s] for s in UNIVERSE])
    raw={s:max(score[s],.02)*(.7+.3*(1/v20[s])/inv) for s in UNIVERSE}
    if med(r20)<0 or med(r30)<0 or np.std(list(r10.values()))>.02:
        for s in ("XAU","US10Y","CN10Y"): raw[s]*=1.30
    target=bounded(raw)
    avg=np.mean(list(score.values())); sd=max(np.std(list(score.values())),1e-9)
    forecast={s:float(.01*(score[s]-avg)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _days_to_rebalance=9

