MIN_W, MAX_W = 0.015, 0.20
_days_to_rebalance = 0


def load_ensemble():
    for p in (Path(__file__).parent / "factors/factor_ensemble.json", Path(__file__).parent / "factor_ensemble.json"):
        try:
            xs = json.loads(p.read_text()).get("selected_factors", [])
            if xs and len(xs) <= 10 and abs(sum(float(x["weight"]) for x in xs) - 1.0) < 1e-6:
                return xs
        except Exception:
            pass
    return []


def percentile(values):
    order = sorted(UNIVERSE, key=lambda s: values[s])
    return {s: (order.index(s) + 1) / len(UNIVERSE) for s in UNIVERSE}


def bounded(raw):
    q = {s: max(float(raw[s]), 1e-12) for s in UNIVERSE}
    for _ in range(50):
        z = sum(q.values())
        nq = {s: q[s] / z for s in UNIVERSE}
        changed = False
        for s in UNIVERSE:
            if nq[s] < MIN_W:
                q[s] = MIN_W; changed = True
            elif nq[s] > MAX_W:
                q[s] = MAX_W; changed = True
            else:
                q[s] = nq[s]
        if not changed:
            q = nq
            break
    z = sum(q.values())
    return {s: q[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in ensemble}

    prices = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=180)
        if df is None or len(df) < 125:
            return
        prices[symbol] = np.asarray(df.sort_values("date")["close"], dtype=float)
    daily = {s: prices[s][1:] / np.maximum(prices[s][:-1], 1e-12) - 1.0 for s in UNIVERSE}
    def ret(n):
        return {s: prices[s][-1] / max(prices[s][-n-1], 1e-12) - 1.0 for s in UNIVERSE}
    r5, r10, r20, r30, r120 = [ret(n) for n in (5, 10, 20, 30, 120)]
    vol20 = {s: max(float(np.std(daily[s][-20:])), .008) for s in UNIVERSE}
    vol40 = {s: max(float(np.std(daily[s][-40:])), .008) for s in UNIVERSE}
    vol60 = {s: max(float(np.std(daily[s][-60:])), .008) for s in UNIVERSE}
    down60 = {s: max(float(np.std(np.minimum(daily[s][-60:], 0))), .006) for s in UNIVERSE}
    med20 = float(np.median(list(r20.values())))
    med30 = float(np.median(list(r30.values())))
    med10_def = float(np.mean([r10[s] for s in ("XAU", "US10Y", "CN10Y")]))
    med = lambda x: float(np.median(list(x.values())))
    rev20 = {s: -(r20[s] - med(r20)) / vol40[s] for s in UNIVERSE}
    rev30 = {s: -(r30[s] - med(r30)) / vol40[s] for s in UNIVERSE}

    signals = {
        "miner_1_20281019_downside_risk_adjusted_reversal": {s: -(r20[s] - med20) / down60[s] for s in UNIVERSE},
        "miner_2_20280113_conditional_medium_reversal_20d": rev20,
        "miner_1_20271118_macro_relative_strength_reversal": {s: -(r10[s] - med10_def) / vol20[s] for s in UNIVERSE},
        "miner_2_20271230_medium_volscaled_reversal_20_30": {s: .6 * rev20[s] + .4 * rev30[s] for s in UNIVERSE},
        "miner_1_20281130_inverted_120d_risk_trend": {s: -r120[s] / (np.sqrt(60) * vol60[s]) for s in UNIVERSE},
        "miner_1_20281214_vol_compression_reversal": {s: -r20[s] * (1 + np.clip(1 - vol20[s] / vol60[s], -.5, .5)) for s in UNIVERSE},
        "miner_3_20290125_lowvol_reversal_5d": {s: -r5[s] / (vol20[s] * np.sqrt(5)) for s in UNIVERSE},
        "miner_2_20280601_vix_stress_reversal_20d": {s: -(r20[s] - med20) / (vol20[s] * (1 + vol20[s] / max(med(vol20), .008))) for s in UNIVERSE},
        "miner_2_20271202_risk_adjusted_momentum_reversal": {s: -(r10[s] - med(r10)) / vol40[s] for s in UNIVERSE},
    }
    score = {s: .5 for s in UNIVERSE}
