    # High-risk sideways/bearish regime: full investment, but explicitly favor defensives.
    if med20 < 0 or med30 < 0 or np.std(list(r10.values())) > .02:
        for s in ("XAU", "US10Y", "CN10Y"):
            raw[s] *= 1.30
    target = bounded(raw)
    mean_score = float(np.mean(list(score.values())))
    score_sd = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mean_score) / score_sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _days_to_rebalance = 9

