    return []


def ranks(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1) / len(UNIVERSE) for i, s in enumerate(ordered)}


def bounded(raw):
    # Iterative clipping followed by normalization preserves a complete target.
    w = {s: max(float(raw[s]), 1e-12) for s in UNIVERSE}
