_days_to_rebalance = 0


def load_ensemble():
    try:
        d = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())
        x = d.get("selected_factors", [])
        if len(x) <= 10 and abs(sum(float(a["weight"]) for a in x)-1) < 1e-6:
            return x
    except Exception:
        pass
    return []


def ranks(x):
    order = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i+1)/len(UNIVERSE) for i, s in enumerate(order)}


def bounded(raw):
    w = {s: max(float(raw[s]), 1e-12) for s in UNIVERSE}
    for _ in range(30):
        z = sum(w.values())
        w = {s: min(MAX_W, max(MIN_W, w[s]/z)) for s in UNIVERSE}
    z = sum(w.values())
    return {s: w[s]/z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    ensemble = load_ensemble()
    if not ensemble:
        return
