DEFENSIVE = ("XAU", "US10Y", "CN10Y")
_next_rebalance = 0


def ensemble():
    try:
        a = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text()).get("selected_factors", [])
        if 0 < len(a) <= 10 and abs(sum(float(x["weight"]) for x in a) - 1.0) < 1e-6:
            return a
    except Exception:
        pass
    return []


def cs_rank(values):
    order = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1) / len(UNIVERSE) for i, s in enumerate(order)}


def project(raw):
    # Positive, full-investment weights; the mild floor prevents accidental
    # concentration in the small 15-asset cross-section.
    w = {s: max(float(raw[s]), 1e-8) for s in UNIVERSE}
    for _ in range(20):
        total = sum(w.values())
        w = {s: min(0.20, max(0.015, w[s] / total)) for s in UNIVERSE}
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _next_rebalance
    if _next_rebalance > 0:
        _next_rebalance -= 1
        return
    factors = ensemble()
    if not factors:
        return

    ids = [str(x["factor_id"]) for x in factors]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in factors}
