    daily = {s: close[s][1:] / np.maximum(close[s][:-1], 1e-12) - 1.0 for s in UNIVERSE}
    def ret(n):
        return {s: close[s][-1] / max(close[s][-n-1], 1e-12) - 1.0 for s in UNIVERSE}
    r5, r10, r20, r30 = [ret(n) for n in (5, 10, 20, 30)]
