    vol40 = {s: max(float(np.std(daily[s][-40:])), .008) for s in UNIVERSE}
    downside = {s: max(float(np.std(np.minimum(daily[s][-60:], 0.0))), .006) for s in UNIVERSE}
    defensive_return = float(np.mean([r10[s] for s in DEFENSIVE]))

