        "miner_2_20280113_conditional_medium_reversal_20d": {s: -(r20[s] - m20) / vol40[s] for s in UNIVERSE},
        "miner_2_20271230_medium_volscaled_reversal_20_30": {s: -.6 * (r20[s] - m20) / vol40[s] - .4 * (r30[s] - m30) / vol40[s] for s in UNIVERSE},
        "miner_2_20290503_breadth_confirmed_trend_5d": {s: .65 * r5[s] / vol20[s] + .35 * r20[s] / vol40[s] for s in UNIVERSE},
        "miner_2_20270923_volnorm_reversal": {s: -r20[s] / vol20[s] for s in UNIVERSE},
        "miner_2_20271202_risk_adjusted_momentum_reversal": {s: -(r10[s] - m10) / vol40[s] for s in UNIVERSE},
        "miner_2_20280601_vix_stress_reversal_20d": {s: -(r20[s] - m20) / vol20[s] for s in UNIVERSE},
    }
    dispersion = float(np.std(list(r5.values())) / max(med(vol20.values()), .008))
    gate = min(1.0, max(0.0, dispersion - 1.0))
