    forecast = {s: float(.01 * (score[s] - mean_score) / std_score) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += float(.002 * tilt)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _next_rebalance = 9

