        if len(x) <= 10 and abs(sum(float(a["weight"]) for a in x)-1) < 1e-6:
            return x
    except Exception:
        pass
    return []

def ranks(x):
    order = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i+1)/len(UNIVERSE) for i, s in enumerate(order)}

def bounded(raw):
    w = {s: max(.02, min(.18, float(raw[s]))) for s in UNIVERSE}
    for _ in range(30):
        gap = sum(w.values())-1
        free = [s for s in UNIVERSE if .02 < w[s] < .18]
        if not free or abs(gap) < 1e-9: break
        for s in free: w[s] = max(.02, min(.18, w[s]-gap/len(free)))
    z = sum(w.values())
    return {s: w[s]/z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _next_rebalance
    if _next_rebalance:
        _next_rebalance -= 1
        return
    fs = ensemble()
    if not fs: return
    ids = [str(a["factor_id"]) for a in fs]
    fw = {str(a["factor_id"]): float(a["weight"]) for a in fs}
