    def r(s, n): return close[s][-1]/max(close[s][-n-1], 1e-12)-1
    r5 = {s:r(s,5) for s in UNIVERSE}; r10={s:r(s,10) for s in UNIVERSE}
    r20={s:r(s,20) for s in UNIVERSE}; r60={s:r(s,60) for s in UNIVERSE}; r120={s:r(s,120) for s in UNIVERSE}
