UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_next_rebalance = 0


def load_ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text()).get("selected_factors", [])
        if len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def ranks(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1) / len(UNIVERSE) for i, s in enumerate(ordered)}


def normalize_weights(raw):
    w = {s: max(0.02, min(0.18, float(raw[s]))) for s in UNIVERSE}
    for _ in range(50):
        gap = sum(w.values()) - 1.0
        free = [s for s in UNIVERSE if 0.020001 < w[s] < 0.179999]
        if not free or abs(gap) < 1e-10:
            break
        for s in free:
            w[s] = max(0.02, min(0.18, w[s] - gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _next_rebalance
    if _next_rebalance:
        _next_rebalance -= 1
        return
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in ensemble}

    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=300)
        if df is None or len(df) < 125:
            return
        closes[symbol] = np.asarray(df.sort_values("date")["close"], dtype=float)
    daily = {s: closes[s][1:] / np.maximum(closes[s][:-1], 1e-12) - 1.0 for s in UNIVERSE}
    def change(s, n):
        return closes[s][-1] / max(closes[s][-n-1], 1e-12) - 1.0

    r5 = {s: change(s, 5) for s in UNIVERSE}
    r20 = {s: change(s, 20) for s in UNIVERSE}
    r60 = {s: change(s, 60) for s in UNIVERSE}
    r120 = {s: change(s, 120) for s in UNIVERSE}
    vol20 = {s: max(float(np.std(daily[s][-20:])), 0.008) for s in UNIVERSE}
    vol40 = {s: max(float(np.std(daily[s][-40:])), 0.008) for s in UNIVERSE}
    downside = {s: max(float(np.sqrt(np.mean(np.minimum(daily[s][-40:], 0.0) ** 2))), 0.006) for s in UNIVERSE}
    median20 = float(np.median(list(r20.values())))
    defensive_return = float(np.mean([r60[s] for s in DEFENSIVE]))
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    market_daily = np.mean([daily[s][-20:] for s in UNIVERSE], axis=0)

    signals = {
        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / vol20[s] for s in UNIVERSE},
        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r120[s] / vol20[s] for s in UNIVERSE},
        "miner_2_20291018_trend_persistence_20d_confirmed": {s: (r20[s] / vol20[s]) * (0.5 + float(np.mean(daily[s][-20:] > 0))) for s in UNIVERSE},
        "miner_2_20290503_breadth_confirmed_trend_5d": {s: (r60[s] / vol40[s]) * (0.5 + breadth) for s in UNIVERSE},
        "miner_3_20290726_defensive_relative_reversal_10d": {s: -(r60[s] - defensive_return) / vol20[s] for s in UNIVERSE},
        "miner_1_20281019_downside_risk_adjusted_reversal": {s: -(r20[s] - median20) / downside[s] for s in UNIVERSE},
        "miner_1_20271118_macro_relative_strength_reversal": {s: -float(np.sum(daily[s][-20:] - market_daily)) / vol20[s] for s in UNIVERSE},
        "miner_2_20290809_relative_strength_reversal_20d": {s: -(r20[s] - median20) / vol40[s] for s in UNIVERSE},
        "miner_2_20280113_conditional_medium_reversal_20d": {s: (-(r20[s] - median20) / vol40[s] if median20 < 0 else 0.0) for s in UNIVERSE},
    }
    score = {s: 0.5 for s in UNIVERSE}
    for fid in factor_ids:
        if fid not in signals:
            return
        ranked = ranks(signals[fid])
        for s in UNIVERSE:
            score[s] += factor_weights[fid] * directions[fid] * (ranked[s] - 0.5)

    risk = min(1.0, max(0.0, float(np.std(list(r20.values()))) /
                         max(float(np.median(list(vol20.values()))), 0.008) / 4.0))
    raw = {s: max(0.02, score[s]) * (1.0 / vol20[s]) ** 0.35 for s in UNIVERSE}
    for s in DEFENSIVE:
        raw[s] *= 1.22 + 0.25 * risk
    target = normalize_weights(raw)
    mean_score = float(np.mean(list(score.values())))
    score_sd = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean_score) / score_sd) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += 0.002 * (1.0 + risk)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _next_rebalance = 9

