from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_days_to_rebalance = 0


def load_ensemble():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        items = json.loads(p.read_text(encoding="utf-8")).get("selected_factors", [])
        if 0 < len(items) <= 10 and abs(sum(float(x["weight"]) for x in items) - 1.0) < 1e-6:
            return items
    except Exception:
        pass
    return []


def percentile(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(ordered)}


def bounded_weights(raw):
    w = {s: min(0.18, max(0.02, float(raw[s]))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if 0.0200001 < w[s] < 0.1799999]
        if not free:
            break
        for s in free:
            w[s] = min(0.18, max(0.02, w[s] - gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}
    factor_directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in ensemble}

    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 125:
            return
        closes[symbol] = np.asarray(df.sort_values("date")["close"], dtype=float)
    rets = {s: closes[s][1:] / np.maximum(closes[s][:-1], 1e-12) - 1.0 for s in UNIVERSE}

    def change(s, n):
        return closes[s][-1] / max(closes[s][-n-1], 1e-12) - 1.0

    r5 = {s: change(s, 5) for s in UNIVERSE}
    r10 = {s: change(s, 10) for s in UNIVERSE}
    r20 = {s: change(s, 20) for s in UNIVERSE}
    r60 = {s: change(s, 60) for s in UNIVERSE}
    vol20 = {s: max(float(np.std(rets[s][-20:])), 0.008) for s in UNIVERSE}
    vol40 = {s: max(float(np.std(rets[s][-40:])), 0.008) for s in UNIVERSE}
    downside = {s: max(float(np.sqrt(np.mean(np.minimum(rets[s][-40:], 0.0) ** 2))), 0.006) for s in UNIVERSE}
    median20 = float(np.median(list(r20.values())))
    median60 = float(np.median(list(r60.values())))
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    defensive_return = float(np.mean([r60[s] for s in DEFENSIVE]))
    equity = {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX"}
    equity_median = float(np.median([r20[s] for s in equity]))

    signals = {
        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / vol20[s] for s in UNIVERSE},
        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r10[s] / vol20[s] for s in UNIVERSE},
        "miner_3_20290726_defensive_relative_reversal_10d": {s: -(r60[s] - defensive_return) / vol20[s] for s in UNIVERSE},
        "miner_1_20281019_downside_risk_adjusted_reversal": {s: -(r20[s] - median20) / downside[s] for s in UNIVERSE},
        "miner_1_20271118_macro_relative_strength_reversal": {s: -(r20[s] - equity_median) / vol40[s] for s in UNIVERSE},
        "miner_2_20290906_downside_quality_10d": {s: -downside[s] / vol40[s] - 0.25 * r5[s] / vol40[s] for s in UNIVERSE},
        "miner_2_20280113_conditional_medium_reversal_20d": {s: -(r60[s] - median60) / vol40[s] for s in UNIVERSE},
