DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_day = 0


def ensemble():
    try:
        x = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())
        a = x.get("selected_factors", [])
        if 0 < len(a) <= 10 and abs(sum(float(i["weight"]) for i in a) - 1.0) < 1e-6:
            return a
    except Exception:
        pass
    return []


def rank(x):
    z = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(z)}


def weights(raw):
    # Mild 2%-18% bounds, followed by a deterministic simplex projection.
    w = {s: max(.02, min(.18, float(raw[s]))) for s in UNIVERSE}
    for _ in range(30):
        d = sum(w.values()) - 1.0
        if abs(d) < 1e-11:
            break
        free = [s for s in UNIVERSE if .020001 < w[s] < .179999]
        if not free:
            break
        for s in free:
            w[s] = max(.02, min(.18, w[s] - d / len(free)))
    # Numerical normalization only; feasible bounds are retained to tolerance.
    d = sum(w.values())
    return {s: w[s] / d for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _day
    if _day:
        _day -= 1
        return
    a = ensemble()
    if not a:
        return
    ids = [str(i["factor_id"]) for i in a]
    fw = {str(i["factor_id"]): float(i["weight"]) for i in a}
