import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_day = 0

def ensemble():
    try:
        xs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())["selected_factors"]
        if len(xs) <= 10 and abs(sum(float(x["weight"]) for x in xs)-1.0) < 1e-6:
            return xs
    except Exception:
        pass
    return []

def percentile(values):
    order = sorted(UNIVERSE, key=lambda s: (values[s], s))
    return {s: (order.index(s)+1)/len(UNIVERSE) for s in UNIVERSE}

def bounded_weights(raw):
    w = {s: .02 for s in UNIVERSE}
    rem = .80
    active = set(UNIVERSE)
    while active and rem > 1e-12:
        z = sum(max(0.0, raw[s]) for s in active)
        if z <= 0: z = float(len(active))
        capped = set()
        for s in active:
            add = rem * (max(0.0, raw[s]) if z else 1.0) / z
            if add >= .16:
                w[s] = .18; rem -= .16; capped.add(s)
        if not capped:
            for s in active: w[s] += rem * max(0.0, raw[s]) / z
            rem = 0.0
        else:
            active -= capped
    # numerical correction while preserving the stated bounds
    err = 1.0 - sum(w.values())
    for s in sorted(UNIVERSE):
        if abs(err) < 1e-12: break
        room = (.18-w[s]) if err > 0 else (w[s]-.02)
        d = np.sign(err) * min(abs(err), max(0.0, room))
        w[s] += d; err -= d
    return w

@register_hook
def cross_asset_strategy():
    global _day
    if _day:
        _day -= 1
        return
    fs = ensemble()
    if not fs:
        return
    factor_ids = [str(x["factor_id"]) for x in fs]
    weights = {str(x["factor_id"]): float(x["weight"]) for x in fs}
    directions = {str(x["factor_id"]): int(x.get("direction", 1)) for x in fs}
    close = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=260)
        if d is None or len(d) < 80:
            return
        close[s] = np.asarray(d.sort_values("date")["close"], dtype=float)
    def ret(s, n): return close[s][-1] / max(close[s][-n-1], 1e-12) - 1.0
    r5 = {s: ret(s, 5) for s in UNIVERSE}; r10 = {s: ret(s, 10) for s in UNIVERSE}; r20 = {s: ret(s, 20) for s in UNIVERSE}
    vol20 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s][-21:], 1e-12))))), .008) for s in UNIVERSE}
    vol60 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s][-61:], 1e-12))))), .008) for s in UNIVERSE}
    med20 = float(np.median(list(r20.values())))
    equity = [s for s in UNIVERSE if s not in DEFENSIVE]
    breadth = float(np.mean([r5[s] > 0 for s in equity]))
    bear = float(np.mean(list(r20.values()))) < 0 and breadth < .45
    downside = {s: max(float(np.std(np.minimum(np.diff(np.log(np.maximum(close[s][-61:], 1e-12))), 0))), .008) for s in UNIVERSE}
    sig = {
      "miner_2_20300207_defensive_relative_strength_20d": {s:(r20[s]-med20)/vol60[s] for s in UNIVERSE},
      "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s:-r10[s]/vol20[s] for s in UNIVERSE},
      "miner_1_20281019_downside_risk_adjusted_reversal": {s:-r10[s]/downside[s] for s in UNIVERSE},
      "miner_2_20291018_trend_persistence_20d_confirmed": {s:(r5[s]+r20[s])/(2*vol60[s]) for s in UNIVERSE},
      "miner_2_20290503_breadth_confirmed_trend_5d": {s:(.5 + .5*breadth)*r5[s]/vol20[s] for s in UNIVERSE},
      "miner_2_20270923_volnorm_reversal": {s:-r5[s]/vol20[s] for s in UNIVERSE}
    }
    score = {s:.5 for s in UNIVERSE}
    for fid in factor_ids:
        ranks = percentile(sig[fid])
        for s in UNIVERSE: score[s] += weights[fid] * directions[fid] * (ranks[s]-.5)
    risk = min(1.0, float(np.std(list(r20.values()))) / max(float(np.median(list(vol20.values()))), .008) / 4.0)
    raw = {s: max(.001, score[s]) * vol60[s]**-.60 for s in UNIVERSE}
    for s in DEFENSIVE: raw[s] *= 1.45 + .35*risk + (.15 if bear else 0.0)
    target = bounded_weights(raw)
    mean, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.035*(score[s]-mean)/sd) for s in UNIVERSE}
    for s in DEFENSIVE: forecast[s] += .006*(1+risk)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _day = 9

