DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_day = 0

def load_ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text()).get("selected_factors", [])
        if 0 < len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []

def percentile(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    n = len(UNIVERSE)
    return {s: (i + 1) / n for i, s in enumerate(ordered)}

def bounded_weights(raw):
    # 2% floor and 18% ceiling, then exact normalization.
    w = {s: 0.02 for s in UNIVERSE}
    remaining = 0.70
    free = set(UNIVERSE)
    while free:
        z = sum(max(float(raw[s]), 1e-9) for s in free)
        hit = {s for s in free if remaining * max(float(raw[s]), 1e-9) / z >= 0.16}
        if not hit:
            for s in free:
                w[s] += remaining * max(float(raw[s]), 1e-9) / z
            break
        for s in hit:
            w[s] = 0.18
        remaining -= 0.16 * len(hit)
        free -= hit
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day
    if _day:
        _day -= 1
        return
    factors = load_ensemble()
    if not factors:
        return
    ids = [str(f["factor_id"]) for f in factors]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in factors}
    directions = {str(f["factor_id"]): int(f.get("direction", 1)) for f in factors}
    close, volume = {}, {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=270)
        if d is None or len(d) < 80:
            return
        d = d.sort_values("date")
