        volume[s] = np.asarray(d["volume"], dtype=float)
    def ret(s, n):
        return close[s][-1] / max(close[s][-n-1], 1e-12) - 1.0
    r5 = {s: ret(s, 5) for s in UNIVERSE}
    r10 = {s: ret(s, 10) for s in UNIVERSE}
    r20 = {s: ret(s, 20) for s in UNIVERSE}
    r60 = {s: ret(s, 60) for s in UNIVERSE}
    logret = {s: np.diff(np.log(np.maximum(close[s], 1e-12))) for s in UNIVERSE}
    v20 = {s: max(float(np.std(logret[s][-20:])), 0.008) for s in UNIVERSE}
    v60 = {s: max(float(np.std(logret[s][-60:])), 0.008) for s in UNIVERSE}
    downside = {s: max(float(np.std(np.minimum(logret[s][-60:], 0))), 0.008) for s in UNIVERSE}
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    median20 = float(np.median(list(r20.values())))
