            return fs
    except Exception:
        pass
    return []


def rank(values):
    # Deterministic cross-sectional percentile rank for the fixed 15-name universe.
    order = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1) / len(UNIVERSE) for i, s in enumerate(order)}


def capped_weights(raw):
    # Full investment, long-only: 2% floor and 18% cap, with exact normalization.
    floor, cap = 0.02, 0.18
    w = {s: floor for s in UNIVERSE}
    free = set(UNIVERSE)
    left = 1.0 - floor * len(UNIVERSE)
    while free and left > 1e-12:
        total = sum(max(float(raw[s]), 1e-12) for s in free)
        proposed = {s: left * max(float(raw[s]), 1e-12) / total for s in free}
        hit = {s for s in free if proposed[s] > cap - floor + 1e-12}
        if not hit:
            for s in free:
                w[s] += proposed[s]
            break
        for s in hit:
            w[s] = cap
            left -= cap - floor
        free -= hit
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
