        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / vol40 for s in UNIVERSE} if False else {s: r20[s] / vol60[s] for s in UNIVERSE},
        "miner_1_20271118_macro_relative_strength_reversal": {s: -r10[s] / vol60[s] + (0.35 if s in DEFENSIVE else 0.0) for s in UNIVERSE},
        "miner_1_20281019_downside_risk_adjusted_reversal": {s: -r10[s] / down60[s] for s in UNIVERSE},
    }
