import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_days_to_rebalance = 0

def ensemble():
    try:
        obj = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        fs = obj.get("selected_factors", [])
        if 0 < len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []

def percentile(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(ordered)}

def bounded_weights(raw):
    floor, cap = 0.02, 0.18
    weights = {s: floor for s in UNIVERSE}
    free, remaining = set(UNIVERSE), 1.0 - floor * len(UNIVERSE)
    while free and remaining > 1e-12:
        denom = sum(max(float(raw[s]), 1e-12) for s in free)
        proposed = {s: remaining * max(float(raw[s]), 1e-12) / denom for s in free}
        clipped = {s for s in free if proposed[s] > cap - floor + 1e-12}
        if not clipped:
            for s in free:
                weights[s] += proposed[s]
            break
        for s in clipped:
            weights[s] = cap
            remaining -= cap - floor
        free -= clipped
    total = sum(weights.values())
    return {s: weights[s] / total for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    factors = ensemble()
    if not factors:
        return
    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=270)
        if df is None or len(df) < 80:
            return
        closes[symbol] = np.asarray(df.sort_values("date")["close"], dtype=float)

    def returns(symbol, n):
        p = closes[symbol]
        return p[-1] / max(p[-n-1], 1e-12) - 1.0

    r5 = {s: returns(s, 5) for s in UNIVERSE}
    r10 = {s: returns(s, 10) for s in UNIVERSE}
    r20 = {s: returns(s, 20) for s in UNIVERSE}
    r60 = {s: returns(s, 60) for s in UNIVERSE}
    log_returns = {s: np.diff(np.log(np.maximum(closes[s], 1e-12))) for s in UNIVERSE}
    v20 = {s: max(float(np.std(log_returns[s][-20:])), 0.008) for s in UNIVERSE}
    v60 = {s: max(float(np.std(log_returns[s][-60:])), 0.008) for s in UNIVERSE}
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    median20 = float(np.median(list(r20.values())))
    stressed = breadth < 0.50
    signals = {
        "miner_2_20300207_defensive_relative_strength_20d": {s: (r20[s] - median20) / v20[s] * (1.35 if stressed else 1.0) * (1.0 if r60[s] > 0 else 0.55) for s in UNIVERSE},
        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / v60[s] for s in UNIVERSE},
        "miner_2_20291018_trend_persistence_20d_confirmed": {s: (r5[s] + r20[s]) / (2.0 * v60[s]) for s in UNIVERSE},
        "miner_2_20290503_breadth_confirmed_trend_5d": {s: r5[s] / v20[s] * (0.5 + 0.5 * breadth) for s in UNIVERSE},
        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r10[s] / v20[s] for s in UNIVERSE},
        "miner_1_20271118_macro_relative_strength_reversal": {s: -r10[s] / v60[s] + (0.35 if s in DEFENSIVE else 0.0) for s in UNIVERSE},
    }
    score = {s: 0.5 for s in UNIVERSE}
    factor_ids = []
    for factor in factors:
        factor_id = str(factor["factor_id"])
        if factor_id not in signals:
            return
        direction, weight = int(factor.get("direction", 1)), float(factor["weight"])
        factor_ids.append(factor_id)
        ranks = percentile(signals[factor_id])
        for s in UNIVERSE:
            score[s] += weight * direction * (ranks[s] - 0.5)

    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(v20.values()))), 0.008) / 4.0)
    raw = {s: max(score[s], 1e-8) / (v60[s] ** 0.60) for s in UNIVERSE}
    # In the screener's high-risk range regime, make defensive assets the
    # explicit full-investment shock absorbers rather than using cash.
    if stressed or risk > 0.75:
        for s in DEFENSIVE:
            raw[s] *= 2.20 + 0.80 * risk
    target = bounded_weights(raw)
    mean_score = float(np.mean(list(score.values())))
    std_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.035 * (score[s] - mean_score) / std_score) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += float(0.010 * (1.0 + risk))
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _days_to_rebalance = 9

