import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_days_to_rebalance = 0


def ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text()).get("selected_factors", [])
        if len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def ranks(x):
    order = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(order)}


def cap_weights(raw):
    # Full investment, modest 2%-18% bounds, with fractional quantities downstream.
    lo, hi = .02, .18
    w = {s: lo for s in UNIVERSE}
    free = set(UNIVERSE); rem = 1.0 - lo * len(UNIVERSE)
    while free and rem > 1e-12:
        den = sum(max(float(raw[s]), 1e-12) for s in free)
        add = {s: rem * max(float(raw[s]), 1e-12) / den for s in free}
        hit = {s for s in free if add[s] >= hi - lo - 1e-12}
        if not hit:
            for s in free: w[s] += add[s]
            break
        for s in hit: w[s] = hi; rem -= hi - lo
        free -= hit
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days_to_rebalance
    if _days_to_rebalance:
        _days_to_rebalance -= 1
        return
    fs = ensemble()
    if not fs:
        return
    close = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=270)
        if df is None or len(df) < 80:
            return
        close[s] = np.asarray(df.sort_values("date")["close"], dtype=float)

    def ret(s, n):
        p = close[s]
        return float(p[-1] / max(p[-n-1], 1e-12) - 1.0)
    r5 = {s: ret(s, 5) for s in UNIVERSE}
    r10 = {s: ret(s, 10) for s in UNIVERSE}
    r20 = {s: ret(s, 20) for s in UNIVERSE}
    vol20 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s], 1e-12)))[-20:])), .008) for s in UNIVERSE}
    vol60 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s], 1e-12)))[-60:])), .008) for s in UNIVERSE}
    med20 = float(np.median(list(r20.values())))
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    stressed = breadth < .50
    # VIX is observation-only; its level gates the short-horizon residual reversal.
    vix = 20.0
    try:
        vd = get_index_daily_data(symbol="VIX", days=30)
        if vd is not None and len(vd): vix = float(vd.sort_values("date")["close"].iloc[-1])
    except Exception:
        pass
    vix_gate = min(1.5, max(.5, vix / 20.0))
    cross_mean = float(np.mean(list(r5.values())))
    signals = {
        "miner_2_20300207_defensive_relative_strength_20d": {s: (r20[s] - med20) / vol20[s] + (.30 if stressed and s in DEFENSIVE else 0.0) for s in UNIVERSE},
        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r10[s] / vol20[s] for s in UNIVERSE},
        "miner_2_20310306_breadth_gated_inverse_trend_20d": {s: (-r20[s] / vol60[s]) * (1.25 if stressed else .70) for s in UNIVERSE},
        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / vol60[s] for s in UNIVERSE},
        "miner_1_20310320_vix_gated_residual_reversal_5d": {s: -(r5[s] - cross_mean) / vol20[s] * vix_gate for s in UNIVERSE},
    }
    score = {s: .5 for s in UNIVERSE}; factor_ids = []
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in signals: return
        factor_ids.append(fid)
        rr = ranks(signals[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - .5)
    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(vol20.values()))), .008) / 4.0)
    raw = {s: max(score[s], 1e-8) / (vol60[s] ** .60) for s in UNIVERSE}
    if stressed or risk > .75:
        for s in DEFENSIVE: raw[s] *= 1.8 + risk
    target = cap_weights(raw)
    mu, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.035 * (score[s] - mu) / sd) for s in UNIVERSE}
    for s in DEFENSIVE: forecast[s] += float(.006 * (1.0 + risk))
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _days_to_rebalance = 9

