import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_days = 0


def load_ensemble():
    try:
        data = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())
        fs = data.get("selected_factors", [])
        if 0 < len(fs) <= 10 and abs(sum(float(f["weight"]) for f in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def percentile(values):
    ordered = sorted(UNIVERSE, key=lambda x: (values[x], x))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(ordered)}


def bounded_weights(raw):
    lo, hi = 0.02, 0.18
    w = {s: lo for s in UNIVERSE}
    free, remaining = set(UNIVERSE), 1.0 - lo * len(UNIVERSE)
    while free and remaining > 1e-12:
        denom = sum(max(raw[s], 1e-12) for s in free)
        proposed = {s: remaining * max(raw[s], 1e-12) / denom for s in free}
        capped = {s for s in free if proposed[s] > hi - lo}
        if not capped:
            for s in free:
                w[s] += proposed[s]
            break
        for s in capped:
            w[s] = hi
            remaining -= hi - lo
        free -= capped
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _days
    if _days:
        _days -= 1
        return
    factors = load_ensemble()
    if not factors:
        return
    closes = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=270)
        if df is None or len(df) < 80:
            return
        closes[s] = np.asarray(df.sort_values("date")["close"], dtype=float)

    def ret(s, n):
        p = closes[s]
        return p[-1] / max(p[-n-1], 1e-12) - 1.0

    r5 = {s: ret(s, 5) for s in UNIVERSE}
    r10 = {s: ret(s, 10) for s in UNIVERSE}
