    v60 = {s: max(float(np.std(np.diff(np.log(np.maximum(closes[s], 1e-12)))[-60:])), .008) for s in UNIVERSE}
    breadth = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    stressed = breadth < .50
    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(v20.values()))), .008) / 4.0)
    med20 = float(np.median(list(r20.values())))

    signals = {
        "miner_2_20300207_defensive_relative_strength_20d": {s: (r20[s] - med20) / v20[s] for s in UNIVERSE},
        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r10[s] / v20[s] for s in UNIVERSE},
