    }
    score = {s: 0.0 for s in UNIVERSE}
    ids = []
    for f in factors:
        fid, wt = str(f["factor_id"]), float(f["weight"])
        if fid not in signals:
            return
        ids.append(fid)
        ranks = percentile(signals[fid])
        for s in UNIVERSE:
            score[s] += wt * int(f.get("direction", 1)) * (ranks[s] - .5)

    raw = {s: max(score[s] + .5, 1e-8) / (v60[s] ** .60) for s in UNIVERSE}
    if stressed or risk > .75:
        for s in DEFENSIVE:
            raw[s] *= 1.8 + risk
    target = bounded_weights(raw)
    mean, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.035 * (score[s] - mean) / sd) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += .006 * (1.0 + risk)
