    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(ordered)}


def bounded_weights(raw):
    # Full investment, diversified 15-asset portfolio; fractional units are handled by helper.
    lo, hi = 0.03, 0.16
    weights = {s: lo for s in UNIVERSE}
