        "miner_2_20310306_breadth_gated_inverse_trend_20d": {s: -r20[s] / vol20[s] * (1.0 if breadth < .5 else .35) for s in UNIVERSE},
    }
    score = {s: 0.0 for s in UNIVERSE}
    factor_ids = []
    for factor in factors:
        fid = str(factor["factor_id"])
        if fid not in signals:
            return
        factor_ids.append(fid)
        ranks = rank(signals[fid])
        for s in UNIVERSE:
            score[s] += float(factor["weight"]) * int(factor.get("direction", 1)) * (ranks[s] - .5)

    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(vol20.values()))), .008) / 4.0)
    raw = {s: max(score[s] + .5, 1e-8) / (vol60[s] ** .60) for s in UNIVERSE}
    # High-risk fragmented leadership: use defensive tradable assets, never cash.
    if breadth < .5 or risk > .55:
        boost = 2.0 + 2.0 * risk
        for s in DEFENSIVE:
            raw[s] *= boost
    target = bounded_weights(raw)

    # Deterministic 10-day cross-sectional forecast required by migration gate.
    mean_score = float(np.mean(list(score.values())))
    std_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.035 * (score[s] - mean_score) / std_score) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += float(.008 * (1.0 + risk))
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _next_decision = 9

