DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_next_decision = 0


def ensemble():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        fs = json.loads(p.read_text()).get("selected_factors", [])
        if not fs or len(fs) > 10 or abs(sum(float(x["weight"]) for x in fs) - 1.0) > 1e-6:
            return []
        return fs
    except Exception:
        return []


def cs_rank(x):
    ordered = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) for i, s in enumerate(ordered)}


def bounded(raw):
    # Diversification is useful here because the cross-section is only 15 assets.
    lo, hi = .03, .16
    w = {s: lo for s in UNIVERSE}
    free, left = set(UNIVERSE), 1.0 - lo * len(UNIVERSE)
    while free and left > 1e-12:
        z = sum(max(raw[s], 1e-12) for s in free)
        add = {s: left * max(raw[s], 1e-12) / z for s in free}
        cap = {s for s in free if add[s] > hi - lo}
        if not cap:
            for s in free: w[s] += add[s]
            break
        for s in cap:
            w[s] = hi
            left -= hi - lo
        free -= cap
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _next_decision
    if _next_decision:
        _next_decision -= 1
        return
