        "miner_3_20290712_inverse_risk_adjusted_trend_10d": {s: -r10[s] / v20[s] for s in UNIVERSE},
        "miner_1_20281019_downside_risk_adjusted_reversal": {s: -(r20[s] - med20) / downside[s] for s in UNIVERSE},
        "miner_2_20280113_conditional_medium_reversal_20d": {s: (-(r20[s] - med20) / v60[s]) * (1.0 if breadth < .55 else .35) for s in UNIVERSE},
        "miner_1_20271118_macro_relative_strength_reversal": {s: -(r5[s] - float(np.median(list(r5.values())))) / v20[s] for s in UNIVERSE},
        "miner_1_20290823_risk_adjusted_intermediate_momentum_20d": {s: r20[s] / v60[s] for s in UNIVERSE},
    }
    score = {s: 0.0 for s in UNIVERSE}
    ids = []
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in signals:
            return
        ids.append(fid)
        rr = cs_rank(signals[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - .5)

    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(v20.values()))), .008) / 4.0)
    raw = {s: max(score[s] + .5, 1e-8) / (v60[s] ** .60) for s in UNIVERSE}
    # Bullish-to-sideways but medium-high risk: keep full investment and favor defensives.
    if breadth < .60 or risk > .45:
        for s in DEFENSIVE:
            raw[s] *= 1.7 + 1.3 * risk
    target = bounded(raw)
    mu, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
