        fs = obj.get("selected_factors", [])
        if len(fs) > 10 or not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
            return []
        return fs
    except Exception:
        return []


def rank(values):
    ordered = sorted(UNIVERSE, key=lambda s: (float(values[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) - 0.5 for i, s in enumerate(ordered)}


def bounded(raw):
    lo, hi = .03, .16
