    free = set(UNIVERSE)
    remain = 1.0 - lo * len(UNIVERSE)
    while free:
        total = sum(max(float(raw[s]), 1e-9) for s in free)
        additions = {s: remain * max(float(raw[s]), 1e-9) / total for s in free}
        capped = {s for s in free if additions[s] > hi - lo}
        if not capped:
            for s in free:
                w[s] += additions[s]
            break
        for s in capped:
            w[s] = hi
            remain -= hi - lo
        free -= capped
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _next_decision
    if _next_decision:
        _next_decision -= 1
        return
    fs = load_ensemble()
    if not fs:
        return
    prices = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=270)
        if d is None or len(d) < 100:
            return
        prices[s] = np.asarray(d.sort_values("date")["close"], dtype=float)
    def ret(s, n):
        return prices[s][-1] / max(prices[s][-n-1], 1e-12) - 1.0
    r10 = {s: ret(s, 10) for s in UNIVERSE}
    r15 = {s: ret(s, 15) for s in UNIVERSE}
    r20 = {s: ret(s, 20) for s in UNIVERSE}
    r30 = {s: ret(s, 30) for s in UNIVERSE}
    logs = {s: np.diff(np.log(np.maximum(prices[s], 1e-12))) for s in UNIVERSE}
