    sig["miner_2_20290906_downside_quality_10d"] = {s: -min(r10[s], 0.0) / dn[s] for s in UNIVERSE}
    sig["miner_1_20271118_macro_relative_strength_reversal"] = {s: -(r30[s] - med30) / v60[s] for s in UNIVERSE}
    sig["miner_1_20281019_downside_risk_adjusted_reversal"] = {s: -(r20[s] - med20) / dn[s] for s in UNIVERSE}
    sig["miner_2_20320624_vol_adjusted_reversal_15d"] = {s: -(r15[s] - med15) / v20[s] for s in UNIVERSE}
    stress_mult = 1.0 if stressed else .25
    sig["miner_3_20320429_breadth_stress_downside_reversal"] = {s: -(r10[s] - med10) / dn[s] * stress_mult for s in UNIVERSE}
    market = np.mean(np.array([logs[s][-80:] for s in UNIVERSE]), axis=0)
    residual30, residual20 = {}, {}
    for s in UNIVERSE:
