        residual20[s] = -float(np.sum(e[-20:])) / max(float(np.std(e[-20:])), .006)
    sig["miner_3_20320610_residual_reversal_30d"] = residual30
    sig["miner_3_20320624_residual_reversal_20d"] = residual20

    score = {s: 0.0 for s in UNIVERSE}
    ids = []
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in sig:
            return
        ids.append(fid)
        rr = rank(sig[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * float(f.get("direction", 1)) * rr[s]
    dispersion = float(np.std(list(r20.values())))
    risk = min(1.0, dispersion / max(float(np.median(list(v20.values()))), .008) / 4.0)
    raw = {s: max(score[s] + .5, 1e-8) / (v60[s] ** .60) for s in UNIVERSE}
    if stressed or risk > .45:
        for s in DEFENSIVE:
            raw[s] *= 1.7 + 1.3 * risk
    target = bounded(raw)
    sd = max(float(np.std(list(score.values()))), 1e-9)
    avg = float(np.mean(list(score.values())))
    forecast = {s: float(.025 * (score[s] - avg) / sd) for s in UNIVERSE}
    for s in DEFENSIVE:
        forecast[s] += .005 * (1.0 + risk)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
