import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
_next_decision = 0


def load_ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text()).get("selected_factors", [])
        if not fs or len(fs) > 10 or abs(sum(float(x["weight"]) for x in fs) - 1.0) > 1e-6:
            return []
        return fs
    except Exception:
        return []


def cs_rank(x):
    a = sorted(UNIVERSE, key=lambda s: (float(x[s]), s))
    return {s: (i + 1.0) / len(UNIVERSE) - .5 for i, s in enumerate(a)}


def bounded(raw):
    lo, hi = .03, .16
    w = {s: lo for s in UNIVERSE}; free = set(UNIVERSE); remain = 1 - lo * len(UNIVERSE)
    while free:
        tot = sum(max(float(raw[s]), 1e-9) for s in free)
        add = {s: remain * max(float(raw[s]), 1e-9) / tot for s in free}
        cap = {s for s in free if add[s] > hi - lo}
        if not cap:
            for s in free: w[s] += add[s]
            break
        for s in cap: w[s] = hi; remain -= hi - lo
        free -= cap
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _next_decision
    if _next_decision:
        _next_decision -= 1
        return
    fs = load_ensemble()
    if not fs: return
    p = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=270)
        if d is None or len(d) < 125: return
        p[s] = np.asarray(d.sort_values("date")["close"], dtype=float)
    def ret(s, n): return p[s][-1] / max(p[s][-n-1], 1e-12) - 1
    r5 = {s: ret(s, 5) for s in UNIVERSE}; r10 = {s: ret(s, 10) for s in UNIVERSE}
    r15 = {s: ret(s, 15) for s in UNIVERSE}; r20 = {s: ret(s, 20) for s in UNIVERSE}
    r60 = {s: ret(s, 60) for s in UNIVERSE}
    logret = {s: np.diff(np.log(np.maximum(p[s], 1e-12))) for s in UNIVERSE}
    v20 = {s: max(float(np.std(logret[s][-20:])), .008) for s in UNIVERSE}
    v30 = {s: max(float(np.std(logret[s][-30:])), .008) for s in UNIVERSE}
    dn40 = {s: max(float(np.std(np.minimum(logret[s][-40:], 0)), .006) for s in UNIVERSE}
    # Correct the factor formulas while keeping every calculation causal.
    med5, med15, med20 = (float(np.median(list(x.values()))) for x in (r5, r15, r20))
    breadth20 = float(np.mean([r20[s] > 0 for s in UNIVERSE]))
    market = np.mean(np.array([logret[s][-120:] for s in UNIVERSE]), axis=0)
    market20 = float(np.sum(market[-20:])); market_std60 = max(float(np.std(market[-60:])), .004)
    sig = {}
    sig["miner_3_20290712_inverse_risk_adjusted_trend_10d"] = {s: -r10[s] / v20[s] for s in UNIVERSE}
    gate = 1.35 if breadth20 < .50 else (.75 if breadth20 > .70 else 1.0)
    sig["miner_2_20300207_defensive_relative_strength_20d"] = {s: (r20[s] - med20) / v20[s] * gate * (1 if r60[s] > 0 else .55) for s in UNIVERSE}
    sig["miner_2_20270923_volnorm_reversal"] = {s: -r5[s] / max(v20[s] * np.sqrt(20), .01) for s in UNIVERSE}
    asset_mean = float(np.mean(list(r20.values())))
    sig["miner_1_20281019_downside_risk_adjusted_reversal"] = {s: -(0.7*r60[s] + .3*r20[s]) / max(dn40[s] * np.sqrt(40), .01) for s in UNIVERSE}
    excess20 = {s: r20[s] - asset_mean for s in UNIVERSE}
    sig["miner_1_20271118_macro_relative_strength_reversal"] = {s: -excess20[s] / v20[s] for s in UNIVERSE}
    sig["miner_2_20320624_vol_adjusted_reversal_15d"] = {s: -r15[s] / max(v30[s] * np.sqrt(252), .01) for s in UNIVERSE}
    short_vol = max(float(np.std(market[-20:])), .004); long_vol = max(float(np.std(market[-120:])), .004)
    stress = 1 + .60 * min(max((.5-breadth20)*2, 0), 1) * min(max(short_vol/long_vol, .5), 2)
    sig["miner_3_20320429_breadth_stress_downside_reversal"] = {s: (-sum(logret[s][-60:]) / max(float(np.std(np.minimum(logret[s][-90:], 0))), .006)) * stress for s in UNIVERSE}
    residual = {}
    for s in UNIVERSE:
        y, x = logret[s][-80:], market[-80:]
        beta = float(np.cov(y, x, ddof=1)[0,1] / max(np.var(x, ddof=1), 1e-10))
        e = y - beta*x
        residual[s] = -sum(e[-20:]) / max(float(np.std(e[-60:])), .006)
    market_gate = 1 + .50 * np.tanh(-market20 / (market_std60 * np.sqrt(20)))
    sig["miner_2_20320805_bearish_state_residual_reversal"] = {s: residual[s] * market_gate for s in UNIVERSE}
    score = {s: 0.0 for s in UNIVERSE}; ids = []
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in sig: return
        ids.append(fid); rr = cs_rank(sig[fid])
        for s in UNIVERSE: score[s] += float(f["weight"]) * float(f.get("direction", 1)) * rr[s]
    dispersion = float(np.std(list(r20.values())))
    risk = min(1., dispersion / max(float(np.median(list(v20.values()))), .008) / 4.)
    raw = {s: max(score[s] + .5, 1e-8) / max(v20[s] ** .60, 1e-6) for s in UNIVERSE}
    if risk > .45 or breadth20 < .5:
        for s in DEFENSIVE: raw[s] *= 1.7 + 1.3*risk
    target = bounded(raw)
    sd = max(float(np.std(list(score.values()))), 1e-9); avg = float(np.mean(list(score.values())))
    forecast = {s: float(.025*(score[s]-avg)/sd) for s in UNIVERSE}
    for s in DEFENSIVE: forecast[s] += .005*(1+risk)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _next_decision = 9

