import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0

def ensemble():
    try:
        x = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        fs = x.get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 and abs(sum(float(f["weight"]) for f in fs)-1) < 1e-6 else []
    except Exception:
        return []

def rank(v):
    order = sorted(U, key=lambda s: (float(v[s]), s))
    return {s: (i + 1) / len(U) - .5 for i, s in enumerate(order)}

def allocate(raw):
    # Full investment with sensible cross-asset concentration limits.
    lo, hi = .03, .18
    w = {s: lo for s in U}; free = set(U); left = 1 - lo*len(U)
    while free:
        z = sum(max(float(raw[s]), 1e-10) for s in free)
        add = {s: left*max(float(raw[s]), 1e-10)/z for s in free}
        capped = {s for s in free if add[s] > hi-lo}
        if not capped:
            for s in free: w[s] += add[s]
            break
        for s in capped: w[s] = hi
        left -= (hi-lo)*len(capped); free -= capped
    z = sum(w.values())
    return {s: w[s]/z for s in U}

@register_hook
def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = ensemble()
    if not fs: return
    p = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=270)
        if d is None or len(d) < 125: return
        p[s] = np.asarray(d.sort_values("date")["close"], dtype=float)
    def ret(s, n): return p[s][-1]/max(p[s][-n-1], 1e-12)-1
    r5, r10, r15, r20, r60 = ({s: ret(s,n) for s in U} for n in (5,10,15,20,60))
    lr = {s: np.diff(np.log(np.maximum(p[s], 1e-12))) for s in U}
    v20 = {s:max(float(np.std(lr[s][-20:])), .008) for s in U}
    v30 = {s:max(float(np.std(lr[s][-30:])), .008) for s in U}
    dn = {s:max(float(np.std(np.minimum(lr[s][-40:],0))), .006) for s in U}
    med20 = float(np.median(list(r20.values())))
    breadth = float(np.mean([r20[s] > 0 for s in U]))
    market = np.mean(np.array([lr[s][-120:] for s in U]), axis=0)
    m20 = float(sum(market[-20:])); mstd = max(float(np.std(market[-60:])), .004)
