DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0

def load_ensemble():
    try:
        d = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        fs = d.get("selected_factors", [])
        if not (0 < len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6):
            return []
        return fs
    except Exception:
        return []

def rank(v):
    ordered = sorted(U, key=lambda s: (float(v[s]), s))
    return {s: (i + 1) / len(U) - 0.5 for i, s in enumerate(ordered)}

def bounded_allocate(raw):
    lo, hi = 0.03, 0.18
    w = {s: lo for s in U}; free = set(U); left = 1.0 - lo * len(U)
    while free:
        z = sum(max(float(raw[s]), 1e-10) for s in free)
        adds = {s: left * max(float(raw[s]), 1e-10) / z for s in free}
        capped = {s for s in free if adds[s] > hi - lo}
        if not capped:
            for s in free: w[s] += adds[s]
            break
        for s in capped: w[s] = hi
        left -= (hi - lo) * len(capped); free -= capped
    z = sum(w.values())
    return {s: w[s] / z for s in U}

