DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0


def ensemble():
    try:
        x = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        fs = x.get("selected_factors", [])
        if len(fs) <= 10 and abs(sum(float(f["weight"]) for f in fs) - 1) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def pct_rank(x):
    order = sorted(U, key=lambda s: (float(x[s]), s))
    return {s: (i + 1) / len(U) - .5 for i, s in enumerate(order)}


def weights(raw):
    # 3%-18% bounds keep the small cross-section diversified.
    lo, hi = .03, .18
    w = {s: lo for s in U}; free = set(U); left = 1 - lo * len(U)
    while free:
        z = sum(max(float(raw[s]), 1e-8) for s in free)
        add = {s: left * max(float(raw[s]), 1e-8) / z for s in free}
        cap = {s for s in free if add[s] > hi - lo}
        if not cap:
            for s in free: w[s] += add[s]
            break
        for s in cap: w[s] = hi
        left -= (hi - lo) * len(cap); free -= cap
    z = sum(w.values())
    return {s: w[s] / z for s in U}


