def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = ensemble()
    if not fs:
        return
    close = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=280)
        if d is None or len(d) < 130:
            return
        close[s] = np.asarray(d.sort_values("date")["close"], dtype=float)

    def r(s, n):
        return close[s][-1] / max(close[s][-n-1], 1e-12) - 1
    r5 = {s: r(s, 5) for s in U}; r10 = {s: r(s, 10) for s in U}
    r20 = {s: r(s, 20) for s in U}; r60 = {s: r(s, 60) for s in U}; r120 = {s: r(s, 120) for s in U}
    vol20 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s][-21:], 1e-12))))), .008) for s in U}
    vol40 = {s: max(float(np.std(np.diff(np.log(np.maximum(close[s][-41:], 1e-12))))), .008) for s in U}
    breadth = np.mean([r20[s] > 0 for s in U])
