import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0

def ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text()).get("selected_factors", [])
        if 0 < len(fs) <= 10 and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []

def rank(v):
    a = sorted(U, key=lambda s: (float(v[s]), s))
    return {s: (i - 7.0) / 14.0 for i, s in enumerate(a)}

def bounded(raw):
    lo, hi = .03, .18
    w = {s: lo for s in U}; free = set(U); rem = 1.0 - lo * len(U)
    while free:
        z = sum(max(float(raw[s]), 1e-9) for s in free)
        add = {s: rem * max(float(raw[s]), 1e-9) / z for s in free}
        cap = {s for s in free if add[s] > hi - lo}
        if not cap:
            for s in free: w[s] += add[s]
            break
        for s in cap: w[s] = hi
        rem -= (hi - lo) * len(cap); free -= cap
    z = sum(w.values())
    return {s: w[s] / z for s in U}

@register_hook
def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = ensemble()
    if not fs:
        return
    dat = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=300)
        if d is None or len(d) < 130:
            return
        dat[s] = d.sort_values("date")
    close = {s: np.asarray(dat[s]["close"], float) for s in U}
    high = {s: np.asarray(dat[s]["high"], float) for s in U}
    low = {s: np.asarray(dat[s]["low"], float) for s in U}
    ret = {s: np.diff(np.log(np.maximum(close[s], 1e-12))) for s in U}
    vol20 = {s: max(float(np.std(ret[s][-20:])), .008) for s in U}
    vol45 = {s: max(float(np.std(ret[s][-45:])), .008) for s in U}
    def R(s, n):
        return close[s][-1] / max(close[s][-n-1], 1e-12) - 1
    r20 = {s: R(s, 20) for s in U}; r40 = {s: R(s, 40) for s in U}
    r60 = {s: R(s, 60) for s in U}; r90 = {s: R(s, 90) for s in U}
    breadth = float(np.mean([r20[s] > 0 for s in U]))
    dispersion = float(np.std(list(r20.values())))
    sig = {}
    for f in fs:
        fid = f["factor_id"]
        if "inverse_trend60" in fid:
            x = {s: -r60[s] / vol20[s] for s in U}
        elif "long_persistence_reversal" in fid:
            x = {s: -r90[s] * (1 + .8 * (np.mean(ret[s][-90:] > 0) - .5)) / vol45[s] for s in U}
        elif "risk_adjusted_intermediate_momentum" in fid:
            x = {s: r20[s] / vol20[s] for s in U}
        elif "trend_efficiency60_inverse" in fid:
            x = {s: -r60[s] / max(float(np.sum(np.abs(ret[s][-60:]))), .01) for s in U}
        elif "downside_quality" in fid:
            x = {}
            for s in U:
                dn = max(float(np.std(ret[s][-60:][ret[s][-60:] < 0])), .008)
                x[s] = -r40[s] / dn
        elif "vol_adjusted_momentum40_inverse" in fid:
            x = {s: -r40[s] / (vol20[s] * np.sqrt(20)) for s in U}
        elif "range_position_reversal" in fid:
            x = {}
            for s in U:
                mn, mx = np.min(close[s][-60:]), np.max(close[s][-60:])
                x[s] = 1.0 - (close[s][-1] - mn) / max(mx - mn, 1e-12)
        elif "breadth_conditioned_trend_reversal" in fid:
            mult = 1.0 - 4.0 * max(.5 - breadth, 0.0)
            x = {s: (-r20[s] / (vol20[s] * np.sqrt(252))) * mult for s in U}
        else:
            return
        sig[fid] = x
    score = {s: 0.0 for s in U}
    for f in fs:
        q = rank(sig[f["factor_id"]])
        for s in U:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * q[s]
    risk = min(1.0, dispersion / .08)
    raw = {s: max(score[s] + .55, 1e-8) / (vol20[s] ** .60) for s in U}
    if breadth < .5 or risk > .55:
        for s in DEF:
            raw[s] *= 1.5 + .5 * risk
    target = bounded(raw)
    sd = max(float(np.std(list(score.values()))), 1e-9); avg = float(np.mean(list(score.values())))
    forecast = {s: float(.025 * (score[s] - avg) / sd) for s in U}
    for s in DEF:
        forecast[s] += float(.004 * (1.0 + risk))
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=[f["factor_id"] for f in fs], horizon_days=10)
    _skip = 9

