DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0


def load_ensemble():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        fs = json.loads(p.read_text(encoding="utf-8")).get("selected_factors", [])
        if 0 < len(fs) <= 10 and abs(sum(float(f["weight"]) for f in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        return []
    return []


def ranks(values):
    ordered = sorted(U, key=lambda s: (float(values[s]), s))
    return {s: (i - 7.0) / 14.0 for i, s in enumerate(ordered)}


def bounded(raw):
    lo, hi = 0.03, 0.18
    w = {s: lo for s in U}
    free, remain = set(U), 1.0 - lo * len(U)
    while free:
        total = sum(max(float(raw[s]), 1e-10) for s in free)
        additions = {s: remain * max(float(raw[s]), 1e-10) / total for s in free}
        capped = {s for s in free if additions[s] > hi - lo}
        if not capped:
            for s in free:
                w[s] += additions[s]
            break
        for s in capped:
            w[s] = hi
        remain -= (hi - lo) * len(capped)
        free -= capped
    total = sum(w.values())
    return {s: w[s] / total for s in U}


@register_hook
def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = load_ensemble()
    if not fs:
        return
    data = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=300)
        if d is None or len(d) < 130:
            return
        data[s] = d.sort_values("date")
    close = {s: np.asarray(data[s]["close"], dtype=float) for s in U}
    logs = {s: np.diff(np.log(np.maximum(close[s], 1e-12))) for s in U}
    v20 = {s: max(float(np.std(logs[s][-20:])), 0.008) for s in U}
    v45 = {s: max(float(np.std(logs[s][-45:])), 0.008) for s in U}
    def ret(s, n):
        return close[s][-1] / max(close[s][-n-1], 1e-12) - 1.0
    r20 = {s: ret(s, 20) for s in U}; r40 = {s: ret(s, 40) for s in U}
    r60 = {s: ret(s, 60) for s in U}; r90 = {s: ret(s, 90) for s in U}
    signals = {}
    for f in fs:
        fid = f["factor_id"]
        if "inverse_trend60" in fid:
            x = {s: -r60[s] / v20[s] for s in U}
        elif "long_persistence_reversal" in fid:
            x = {s: -r90[s] * (1.0 + 0.8 * (np.mean(logs[s][-90:] > 0) - 0.5)) / v45[s] for s in U}
        elif "trend_persistence_reversal" in fid:
            x = {s: -r60[s] * (1.0 + abs(r60[s]) / max(float(np.sum(abs(logs[s][-60:]))), .01)) / v45[s] for s in U}
        elif "risk_adjusted_intermediate_momentum" in fid:
            x = {s: r20[s] / v20[s] for s in U}
        elif "trend_efficiency60_inverse" in fid:
            x = {s: -abs(r60[s]) / max(float(np.sum(abs(logs[s][-60:]))), .01) for s in U}
        elif "downside_quality" in fid:
            x = {s: -r40[s] / max(float(np.std(logs[s][-60:][logs[s][-60:] < 0])), .008) for s in U}
        elif "vol_adjusted_momentum40_inverse" in fid:
            x = {s: -r40[s] / (v20[s] * np.sqrt(20.0)) for s in U}
        elif "reversal40_vol20" in fid:
            x = {s: -r40[s] / v20[s] for s in U}
        else:
            return
        signals[fid] = x
    score = {s: 0.0 for s in U}
    for f in fs:
        q = ranks(signals[f["factor_id"]])
        for s in U:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * q[s]
    dispersion = float(np.std(list(r20.values())))
    breadth = float(np.mean([r20[s] > 0 for s in U]))
    risk = min(1.0, dispersion / 0.08)
    raw = {s: max(score[s] + 0.55, 1e-8) / (v20[s] ** 0.60) for s in U}
    if breadth < 0.5 or risk > 0.55:
        for s in DEF:
            raw[s] *= 1.5 + 0.5 * risk
    target = bounded(raw)
    scale = max(float(np.std(list(score.values()))), 1e-9)
    mean = float(np.mean(list(score.values())))
    forecast = {s: float(0.025 * (score[s] - mean) / scale) for s in U}
    for s in DEF:
        forecast[s] += 0.004 * (1.0 + risk)
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f["factor_id"] for f in fs], horizon_days=10)
    _skip = 9

