import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEF = {"XAU", "US10Y", "CN10Y"}
_skip = 0

def ensemble():
    try:
        fs = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())['selected_factors']
        if len(fs) <= 10 and abs(sum(float(f['weight']) for f in fs)-1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []

def rank(x):
    a = sorted(U, key=lambda s: (float(x[s]), s))
    return {s: (i-7.0)/14.0 for i, s in enumerate(a)}

def bounded(raw):
    lo, hi = .03, .18
    w = {s: lo for s in U}; free = set(U); rem = 1.0 - lo*len(U)
    while free:
        z = sum(max(float(raw[s]), 1e-12) for s in free)
        add = {s: rem*max(float(raw[s]), 1e-12)/z for s in free}
        cap = {s for s in free if add[s] > hi-lo}
        if not cap:
            for s in free: w[s] += add[s]
            break
        for s in cap: w[s] = hi
        rem -= (hi-lo)*len(cap); free -= cap
    z = sum(w.values())
    return {s: w[s]/z for s in U}

@register_hook
def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = ensemble()
    if not fs or {f['factor_id'] for f in fs} != {
        'miner_2_20330915_long_persistence_reversal_90d',
        'miner_1_20331027_inverse_trend60_vol20',
        'miner_1_20290823_risk_adjusted_intermediate_momentum_20d',
        'miner_2_20330901_trend_persistence_reversal_60d',
        'miner_2_20330818_downside_quality_reversal_40d',
        'miner_2_20331027_trend_efficiency60_inverse',
        'miner_2_20330804_path_efficiency_reversal_10d'}:
        return
    ds = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=300)
        if d is None or len(d) < 130: return
        ds[s] = d.sort_values('date')
    c = {s: np.maximum(np.asarray(ds[s]['close'], float), 1e-12) for s in U}
    lr = {s: np.diff(np.log(c[s])) for s in U}
    v20 = {s: max(float(np.std(lr[s][-20:])), .008) for s in U}
    v45 = {s: max(float(np.std(lr[s][-45:])), .008) for s in U}
    def R(s, n): return c[s][-1]/c[s][-n-1]-1.0
    r20={s:R(s,20) for s in U}; r40={s:R(s,40) for s in U}; r60={s:R(s,60) for s in U}; r90={s:R(s,90) for s in U}
    signals = {}
    for f in fs:
        fid = f['factor_id']
        if fid == 'miner_2_20330915_long_persistence_reversal_90d':
            x={s:-r90[s]*(1+.8*(np.mean(lr[s][-90:]>0)-.5))/v45[s] for s in U}
        elif fid == 'miner_1_20331027_inverse_trend60_vol20': x={s:-r60[s]/v20[s] for s in U}
        elif fid == 'miner_1_20290823_risk_adjusted_intermediate_momentum_20d': x={s:r20[s]/v20[s] for s in U}
        elif fid == 'miner_2_20330901_trend_persistence_reversal_60d':
            x={s:-r60[s]*(1+abs(r60[s])/max(float(np.sum(abs(lr[s][-60:]))),.01))/v45[s] for s in U}
        elif fid == 'miner_2_20330818_downside_quality_reversal_40d':
            x={s:-r40[s]/max(float(np.std(lr[s][-60:][lr[s][-60:]<0])),.008) for s in U}
        elif fid == 'miner_2_20331027_trend_efficiency60_inverse':
            x={s:-abs(r60[s])/max(float(np.sum(abs(lr[s][-60:]))),.01) for s in U}
        elif fid == 'miner_2_20330804_path_efficiency_reversal_10d':
            x={s:-(R(s,10)/max(float(np.sum(abs(lr[s][-10:]))),.01))/v20[s] for s in U}
        else: return
        signals[fid] = x
    score={s:0.0 for s in U}
    for f in fs:
        q=rank(signals[f['factor_id']])
        for s in U: score[s] += float(f['weight'])*int(f.get('direction',1))*q[s]
    dispersion=float(np.std(list(r20.values()))); breadth=float(np.mean([r20[s]>0 for s in U])); risk=min(1.0,dispersion/.08)
    raw={s:max(score[s]+.55,1e-8)/(v20[s]**.60) for s in U}
    if breadth < .5 or risk > .55:
        for s in DEF: raw[s] *= 1.5+.5*risk
    target=bounded(raw)
    sd=max(float(np.std(list(score.values()))),1e-9); mu=float(np.mean(list(score.values())))
    forecast={s:float(.025*(score[s]-mu)/sd) for s in U}
    for s in DEF: forecast[s] += .004*(1+risk)
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=[f['factor_id'] for f in fs], horizon_days=10)
    _skip=9

