    order = sorted(U, key=lambda s: (float(x[s]), s))
    return {s: (i - 7.0) / 14.0 for i, s in enumerate(order)}


def bounded(raw):
    # Diversified full-investment portfolio: no cash sleeve, fractional weights.
    lo, hi = 0.025, 0.20
    w = {s: lo for s in U}
    rem, free = 1.0 - lo * len(U), set(U)
    while free:
        z = sum(max(float(raw[s]), 1e-12) for s in free)
        add = {s: rem * max(float(raw[s]), 1e-12) / z for s in free}
        capped = {s for s in free if add[s] > hi - lo}
        if not capped:
            for s in free: w[s] += add[s]
            break
        for s in capped: w[s] = hi
        rem -= (hi - lo) * len(capped)
        free -= capped
    z = sum(w.values())
    return {s: w[s] / z for s in U}


@register_hook
def cross_asset_strategy():
    global _skip
    if _skip:
        _skip -= 1
        return
    fs = load_factors()
