    v20 = {s: max(float(np.std(lr[s][-20:])), .008) for s in U}
    v45 = {s: max(float(np.std(lr[s][-45:])), .008) for s in U}
    def ret(s, n): return close[s][-1] / close[s][-n-1] - 1.0
    r10 = {s: ret(s, 10) for s in U}; r20 = {s: ret(s, 20) for s in U}
    r40 = {s: ret(s, 40) for s in U}; r60 = {s: ret(s, 60) for s in U}; r90 = {s: ret(s, 90) for s in U}
    sig = {}
    for f in fs:
        fid = f["factor_id"]
        if fid == "miner_1_20331027_inverse_trend60_vol20":
            x = {s: -r60[s] / v20[s] for s in U}
        elif fid == "miner_2_20330915_long_persistence_reversal_90d":
            x = {s: -r90[s] * (1 + .8 * (np.mean(lr[s][-90:] > 0) - .5)) / v45[s] for s in U}
        elif fid == "miner_2_20330901_trend_persistence_reversal_60d":
            x = {s: -r60[s] * (1 + abs(r60[s]) / max(float(np.sum(abs(lr[s][-60:]))), .01)) / v45[s] for s in U}
        elif fid == "miner_2_20331208_vol_adjusted_momentum40_inverse":
            x = {s: -r40[s] / v45[s] for s in U}
        elif fid == "miner_1_20330929_reversal40_vol20":
            x = {s: -r40[s] / v20[s] for s in U}
        elif fid == "miner_1_20290823_risk_adjusted_intermediate_momentum_20d":
            x = {s: r20[s] / v20[s] for s in U}
        elif fid == "miner_2_20330804_path_efficiency_reversal_10d":
            x = {s: -(r10[s] / max(float(np.sum(abs(lr[s][-10:]))), .01)) / v20[s] for s in U}
        else:
            return
        sig[fid] = x
    score = {s: 0.0 for s in U}
    for f in fs:
        rr = ranks(sig[f["factor_id"]])
        for s in U: score[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]
    breadth = np.mean([r20[s] > 0 for s in U])
    risk = min(1.0, float(np.std(list(r20.values()))) / .08)
    raw = {s: max(score[s] + .55, 1e-8) / (v20[s] ** .60) for s in U}
    if breadth < .5 or risk > .55:
        for s in DEF: raw[s] *= 1.5 + .5 * risk
    target = bounded(raw)
    sd = max(float(np.std(list(score.values()))), 1e-9)
    mu = float(np.mean(list(score.values())))
    forecast = {s: float(.025 * (score[s] - mu) / sd) for s in U}
    for s in DEF: forecast[s] += .004 * (1 + risk)
    rebalance_to_weights(target, forecast_returns=forecast,
